127	// saveCache saves the version check cache to disk.
128	// Uses atomic write semantics (write to temp file, then rename).
129	func saveCache(cache *VersionCache) error {
130		filePath, err := cacheFilePath()
131		if err != nil {
132			return err
133		}
134	
135		// Marshal to JSON
136		data, err := json.MarshalIndent(cache, "", "  ")
137		if err != nil {
138			return fmt.Errorf("marshaling cache: %w", err)
139		}
140	
141		// Write to temp file first (atomic write)
142		dir := filepath.Dir(filePath)
143		tmpFile, err := os.CreateTemp(dir, ".version_check_tmp_")
144		if err != nil {
145			return fmt.Errorf("creating temp file: %w", err)
146		}
147		defer os.Remove(tmpFile.Name())
148	
149		if _, err := tmpFile.Write(data); err != nil {
150			_ = tmpFile.Close() // cleanup on error path
151			return fmt.Errorf("writing cache: %w", err)
152		}
153	
154		if err := tmpFile.Close(); err != nil {
155			return fmt.Errorf("closing temp file: %w", err)
156		}
157	
158		// Rename temp file to final location
159	
160		if err := os.Rename(tmpFile.Name(), filePath); err != nil {
161			return fmt.Errorf("renaming cache file: %w", err)
162		}
163	
164		return nil
165	}
