167	// fetchLatestVersion fetches the latest version from the GitHub API.
168	// Returns a timeout-safe version check using the configured HTTP timeout.
169	func fetchLatestVersion(ctx context.Context) (string, error) {
170		// Create a context with timeout for the HTTP request
171		ctx, cancel := context.WithTimeout(ctx, httpTimeout)
172		defer cancel()
173	
174		req, err := http.NewRequestWithContext(ctx, http.MethodGet, githubAPIURL, nil)
175		if err != nil {
176			return "", fmt.Errorf("creating request: %w", err)
177		}
178	
179		// Set headers to identify as Entire CLI
180		req.Header.Set("Accept", "application/vnd.github+json")
181		req.Header.Set("User-Agent", "entire-cli")
182	
183		client := &http.Client{}
184		resp, err := client.Do(req)
185		if err != nil {
186			return "", fmt.Errorf("fetching release info: %w", err)
187		}
188		defer resp.Body.Close()
189	
190		if resp.StatusCode != http.StatusOK {
191			return "", fmt.Errorf("unexpected status code: %d", resp.StatusCode)
192		}
193	
194		// Read response body (limit to 1MB to prevent memory exhaustion)
195		body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
196		if err != nil {
197			return "", fmt.Errorf("reading response: %w", err)
198		}
199	
200		// Parse GitHub release response
201		version, err := parseGitHubRelease(body)
202		if err != nil {
203			return "", fmt.Errorf("parsing release: %w", err)
204		}
205	
206		return version, nil
207	}
