209	// isNightly returns true if the version string is a nightly build.
210	func isNightly(version string) bool {
211		if !strings.HasPrefix(version, "v") {
212			version = "v" + version
213		}
214		return strings.Contains(semver.Prerelease(version), "nightly")
215	}
