219		ctx, cancel := context.WithTimeout(ctx, httpTimeout)
220		defer cancel()
221	
222		req, err := http.NewRequestWithContext(ctx, http.MethodGet, githubReleasesURL+"?per_page=20", nil)
223		if err != nil {
224			return "", fmt.Errorf("creating request: %w", err)
225		}
226	
227		req.Header.Set("Accept", "application/vnd.github+json")
228		req.Header.Set("User-Agent", "entire-cli/"+versioninfo.Version)
229	
230		client := &http.Client{}
231		resp, err := client.Do(req)
232		if err != nil {
233			return "", fmt.Errorf("fetching releases: %w", err)
234		}
235		defer resp.Body.Close()
236	
237		if resp.StatusCode != http.StatusOK {
238			return "", fmt.Errorf("unexpected status code: %d", resp.StatusCode)
239		}
240	
241		body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
242		if err != nil {
243			return "", fmt.Errorf("reading response: %w", err)
244		}
245	
246		var releases []GitHubRelease
247		if err := json.Unmarshal(body, &releases); err != nil {
248			return "", fmt.Errorf("parsing JSON: %w", err)
249		}
250	
251		for _, r := range releases {
252			if r.Prerelease && strings.Contains(r.TagName, "-nightly.") {
253				return r.TagName, nil
254			}
255		}
256	
257		return "", errors.New("no nightly release found")
258	}
