260	// parseGitHubRelease parses the GitHub API response and extracts the latest stable version.
261	// Filters out prerelease versions.
262	func parseGitHubRelease(body []byte) (string, error) {
263		var release GitHubRelease
264		if err := json.Unmarshal(body, &release); err != nil {
265			return "", fmt.Errorf("parsing JSON: %w", err)
266		}
267	
268		// Skip prerelease versions
269		if release.Prerelease {
270			return "", errors.New("only prerelease versions available")
271		}
272	
273		// Ensure we have a tag name
274		if release.TagName == "" {
275			return "", errors.New("empty tag name")
276		}
277	
278		return release.TagName, nil
279	}
