281	// isOutdated compares current and latest versions using semantic versioning.
282	// Returns true if current < latest.
283	func isOutdated(current, latest string) bool {
284		// Ensure versions have "v" prefix for semver package
285		if !strings.HasPrefix(current, "v") {
286			current = "v" + current
287		}
288		if !strings.HasPrefix(latest, "v") {
289			latest = "v" + latest
290		}
291	
292		// Skip notification for dev builds (e.g., "1.0.0-dev-xxx").
293		// These are local development builds and shouldn't trigger update notifications.
294		// Normal prereleases (e.g., "1.0.0-rc1") should still be compared normally.
295		if strings.Contains(semver.Prerelease(current), "dev") {
296			return false
297		}
298	
299		// semver.Compare returns -1 if current < latest
300		return semver.Compare(current, latest) < 0
301	}
