319	func loadInstallProvenance() (*InstallProvenance, error) {
320		filePath, err := installProvenanceFilePath()
321		if err != nil {
322			return nil, err
323		}
324	
325		data, err := os.ReadFile(filePath) //nolint:gosec // filePath is inside the user's config dir
326		if err != nil {
327			return nil, fmt.Errorf("reading install provenance: %w", err)
328		}
329	
330		var provenance InstallProvenance
331		if err := json.Unmarshal(data, &provenance); err != nil {
332			return nil, fmt.Errorf("parsing install provenance: %w", err)
333		}
334	
335		return &provenance, nil
336	}
