338	func resolveUpdateHintFromProvenance(provenance *InstallProvenance) (updateHint, bool) {
339		if provenance == nil {
340			return updateHint{}, false
341		}
342	
343		channel := strings.TrimSpace(provenance.Channel)
344		if channel == "" {
345			channel = "stable"
346		}
347	
348		switch strings.TrimSpace(provenance.Manager) {
349		case "install.sh":
350			if channel != "stable" {
351				return updateHint{}, false
352			}
353			return updateHint{Command: "curl -fsSL https://entire.io/install.sh | bash"}, true
354		case "brew":
355			if channel != "stable" && channel != "nightly" {
356				return updateHint{}, false
357			}
358			pkg := strings.TrimSpace(provenance.Package)
359			if pkg == "" {
360				pkg = "entire"
361			}
362			return updateHint{Command: "brew upgrade " + pkg}, true
363		case "scoop":
364			if channel != "stable" && channel != "nightly" {
365				return updateHint{}, false
366			}
367			pkg := strings.TrimSpace(provenance.Package)
368			if pkg == "" {
369				pkg = "entire/cli"
370			}
371			return updateHint{Command: "scoop update " + pkg}, true
372		default:
373			return updateHint{}, false
374		}
375	}
376	
377	func inferUpdateHintFromExecutablePath() updateHint {
378		execPath, err := executablePath()
379		if err != nil {
380			return updateHint{Command: "curl -fsSL https://entire.io/install.sh | bash"}
381		}
382	
383		// Resolve symlinks to find the real path (Homebrew symlinks from bin/ to Cellar/)
384		realPath, err := filepath.EvalSymlinks(execPath)
385		if err != nil {
386			realPath = execPath
387		}
388	
389		if strings.Contains(realPath, "/Cellar/") || strings.Contains(realPath, "/opt/homebrew/") || strings.Contains(realPath, "/linuxbrew/") {
390			return updateHint{Command: "brew upgrade entire"}
391		}
392	
393		if strings.Contains(realPath, "/mise/installs/") {
394			return updateHint{Command: "mise upgrade entire"}
395		}
396	
397		return updateHint{Command: "curl -fsSL https://entire.io/install.sh | bash"}
398	}
399	
400	// updateCommand returns the appropriate update instruction based on install provenance,
401	// falling back to path heuristics for backwards compatibility.
402	func updateCommand() string {
403		provenance, err := loadInstallProvenance()
404		if err == nil {
405			if hint, ok := resolveUpdateHintFromProvenance(provenance); ok {
406				return hint.Command
407			}
408		}
409	
410		return inferUpdateHintFromExecutablePath().Command
411	}
