413	// printNotification prints the version update notification to the user.
414	func printNotification(w io.Writer, current, latest string) {
415		msg := fmt.Sprintf("\nA newer version of Entire CLI is available: %s (current: %s)\nRun '%s' to update.\n",
416			latest, current, updateCommand())
417		fmt.Fprint(w, msg)
418	}
