19	func TestIsOutdated(t *testing.T) {
20		tests := []struct {
21			current string
22			latest  string
23			want    bool
24			desc    string
25		}{
26			// Standard semver cases
27			{"1.0.0", "1.0.1", true, "patch version bump"},
28			{"1.0.0", "1.1.0", true, "minor version bump"},
29			{"1.0.0", "2.0.0", true, "major version bump"},
30			{"1.0.1", "1.0.0", false, "current is newer"},
31			{"2.0.0", "1.9.9", false, "current major is higher"},
32			{"1.0.0", "1.0.0", false, "same version"},
33	
34			// v-prefix handling
35			{"v1.0.0", "v1.0.1", true, "with v prefix"},
36			{"v1.0.0", "1.0.1", true, "mixed v prefix"},
37			{"1.0.0", "v1.0.1", true, "mixed v prefix reversed"},
38	
39			// Pre-release versions (semver uses hyphen)
40			{"1.0.0-rc1", "1.0.0", true, "prerelease in current"},
41			{"1.0.0", "1.0.1-rc1", true, "prerelease in latest is still newer"},
42			{"1.0.0-dev-xxx", "1.0.1", false, "dev build skips version check"},
43	
44			// Nightly-vs-nightly comparisons (same channel)
45			{"0.5.3-nightly.202604051159.abc1234", "0.5.3-nightly.202604061200.def5678", true, "older nightly is outdated by newer nightly"},
46			{"0.5.3-nightly.202604061200.def5678", "0.5.3-nightly.202604051159.abc1234", false, "newer nightly is not outdated by older nightly"},
47			{"0.5.3-nightly.202604061200.abc1234", "0.5.3-nightly.202604061200.abc1234", false, "same nightly is not outdated"},
48		}
49	
50		for _, tt := range tests {
51			t.Run(tt.desc, func(t *testing.T) {
52				got := isOutdated(tt.current, tt.latest)
53				if got != tt.want {
54					t.Errorf("isOutdated(%q, %q) = %v, want %v", tt.current, tt.latest, got, tt.want)
55				}
56			})
57		}
58	}
