package versioncheck

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"runtime"
	"time"

	"github.com/charmbracelet/huh"
	"golang.org/x/term"

	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/settings"
)

const (
	// autoUpdateSoakDuration is how long a release must have been published
	// before "auto" mode will install it unattended. Cushions against bad
	// releases: prompt mode still installs immediately.
	autoUpdateSoakDuration = 24 * time.Hour

	// autoUpdateRetryCooldown is how long to wait after a failed attempt
	// before retrying in "auto" mode.
	autoUpdateRetryCooldown = 24 * time.Hour

	// envKillSwitch disables all auto-update behavior regardless of setting.
	envKillSwitch = "ENTIRE_NO_AUTO_UPDATE"
)

// Test seams.
var (
	runInstaller     = realRunInstaller
	loadGlobal       = settings.LoadGlobal
	nowFunc          = time.Now
	stdoutIsTerminal = defaultStdoutIsTerminal
)

func defaultStdoutIsTerminal() bool {
	return term.IsTerminal(int(os.Stdout.Fd()))
}

// MaybeAutoUpdate offers or runs an auto-update after a newer release is
// detected. The caller has already printed the standard "version available"
// notification. This function is silent on every error path — failures must
// never interrupt the CLI.
func MaybeAutoUpdate(ctx context.Context, w io.Writer, currentVersion string, release *GitHubRelease) {
	if release == nil {
		return
	}
	if os.Getenv(envKillSwitch) != "" {
		logging.Debug(ctx, "auto-update: skipped by kill-switch env")
		return
	}
	if os.Getenv("CI") != "" {
		logging.Debug(ctx, "auto-update: skipped in CI")
		return
	}

	g, err := loadGlobal()
	if err != nil {
		logging.Debug(ctx, "auto-update: load global settings failed", "error", err.Error())
		return
	}
	mode := g.GetAutoUpdate()
	if mode == settings.AutoUpdateOff {
		return
	}

	if !stdoutIsTerminal() {
		logging.Debug(ctx, "auto-update: skipped (no TTY)")
		return
	}

	cmdStr, fromProvenance := resolveUpdateCommand()

	if mode == settings.AutoUpdateAuto {
		if !fromProvenance {
			logging.Debug(ctx, "auto-update: skipped (no install provenance)")
			return
		}
		if !release.PublishedAt.IsZero() && nowFunc().Sub(release.PublishedAt) < autoUpdateSoakDuration {
			logging.Debug(ctx, "auto-update: skipped (release under soak delay)")
			return
		}
		if cache, cerr := loadCache(); cerr == nil {
			if !cache.LastUpdateAttemptTime.IsZero() && !cache.LastUpdateAttemptOk &&
				nowFunc().Sub(cache.LastUpdateAttemptTime) < autoUpdateRetryCooldown {
				logging.Debug(ctx, "auto-update: skipped (recent failure)")
				return
			}
		}
	}

	if mode == settings.AutoUpdatePrompt {
		confirmed, perr := confirmUpdate(release.TagName)
		if perr != nil {
			logging.Debug(ctx, "auto-update: prompt failed", "error", perr.Error())
			return
		}
		if !confirmed {
			return
		}
	}

	fmt.Fprintf(w, "\nUpdating Entire CLI: %s\n", cmdStr)
	runErr := runInstaller(ctx, cmdStr)
	recordUpdateAttempt(ctx, runErr == nil)
	if runErr != nil {
		fmt.Fprintf(w, "Update failed: %v\n", runErr)
		return
	}
	fmt.Fprintf(w, "Update complete. Re-run entire to use the new version.\n")
	_ = currentVersion // reserved for future "updated from X to Y" messaging
}

// confirmUpdate prompts the user interactively. Returns false if they declined
// or aborted (Ctrl-C / timeout), true only on explicit yes.
func confirmUpdate(latest string) (bool, error) {
	var confirmed bool
	form := huh.NewForm(
		huh.NewGroup(
			huh.NewConfirm().
				Title(fmt.Sprintf("Install Entire CLI %s now?", latest)).
				Affirmative("Yes").
				Negative("No").
				Value(&confirmed),
		),
	).WithTheme(huh.ThemeDracula())
	if os.Getenv("ACCESSIBLE") != "" {
		form = form.WithAccessible(true)
	}
	if err := form.Run(); err != nil {
		if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, huh.ErrTimeout) {
			return false, nil
		}
		return false, err
	}
	return confirmed, nil
}

// realRunInstaller shells out to the installer command, streaming stdin/stdout/stderr
// so password prompts and progress output reach the user.
func realRunInstaller(ctx context.Context, cmdStr string) error {
	var c *exec.Cmd
	if runtime.GOOS == "windows" {
		//nolint:gosec // cmdStr comes from provenance resolution, not user input
		c = exec.CommandContext(ctx, "cmd", "/C", cmdStr)
	} else {
		//nolint:gosec // cmdStr comes from provenance resolution, not user input
		c = exec.CommandContext(ctx, "sh", "-c", cmdStr)
	}
	c.Stdin = os.Stdin
	c.Stdout = os.Stdout
	c.Stderr = os.Stderr
	if err := c.Run(); err != nil {
		return fmt.Errorf("installer exited: %w", err)
	}
	return nil
}

// recordUpdateAttempt persists the outcome of the last install attempt so
// "auto" mode can back off after failures.
func recordUpdateAttempt(ctx context.Context, ok bool) {
	cache, err := loadCache()
	if err != nil {
		cache = &VersionCache{}
	}
	cache.LastUpdateAttemptTime = nowFunc()
	cache.LastUpdateAttemptOk = ok
	if err := saveCache(cache); err != nil {
		logging.Debug(ctx, "auto-update: save cache failed", "error", err.Error())
	}
}

// RunUpdateNow is the one-shot update entry point used by `entire update`.
// It ignores the 24h check cache and the auto_update mode gate, but still
// respects the kill-switch env, TTY/CI checks (unless skipPrompt is true),
// and resolves the installer command from provenance.
// Returns (ran bool, err error). ran=false means the user declined or
// the gates blocked execution; err indicates a real failure.
func RunUpdateNow(ctx context.Context, w io.Writer, checkOnly, skipPrompt bool) (bool, error) {
	if os.Getenv(envKillSwitch) != "" {
		return false, errors.New("auto-update disabled by " + envKillSwitch)
	}

	cmdStr, fromProvenance := resolveUpdateCommand()
	if checkOnly {
		if fromProvenance {
			fmt.Fprintf(w, "Update command (from install provenance): %s\n", cmdStr)
		} else {
			fmt.Fprintf(w, "Update command (inferred from executable path): %s\n", cmdStr)
		}
		return false, nil
	}

	if !skipPrompt {
		if !stdoutIsTerminal() {
			return false, errors.New("refusing to run installer on non-TTY stdout (use --yes)")
		}
		confirmed, perr := confirmUpdate("")
		if perr != nil {
			return false, fmt.Errorf("prompt: %w", perr)
		}
		if !confirmed {
			return false, nil
		}
	}

	fmt.Fprintf(w, "\nUpdating Entire CLI: %s\n", cmdStr)
	runErr := runInstaller(ctx, cmdStr)
	recordUpdateAttempt(ctx, runErr == nil)
	if runErr != nil {
		return false, fmt.Errorf("installer: %w", runErr)
	}
	fmt.Fprintf(w, "Update complete. Re-run entire to use the new version.\n")
	return true, nil
}

package cli

import (
	"fmt"
	"io"
	"time"

	"github.com/spf13/cobra"

	"github.com/entireio/cli/cmd/entire/cli/settings"
)

const autoUpdateLong = `Control whether Entire checks for and installs new versions automatically.

Modes:
  off     Show update notifications only (default).
  prompt  Notify and ask Y/N to install when an update is detected.
  auto    Install new releases silently after a 24h soak delay.

Auto-update requires install provenance (written by install.sh, brew, or
scoop). Users who built from source or installed via mise will continue to
see the notification hint.

Settings live at ~/.config/entire/settings.json (machine-wide).
Override at runtime with ENTIRE_NO_AUTO_UPDATE=1.`

func newAutoUpdateCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "auto-update",
		Short: "Configure automatic CLI updates",
		Long:  autoUpdateLong,
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runAutoUpdateStatus(cmd.OutOrStdout())
		},
	}

	cmd.AddCommand(&cobra.Command{
		Use:   "status",
		Short: "Print current auto-update mode",
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runAutoUpdateStatus(cmd.OutOrStdout())
		},
	})

	cmd.AddCommand(&cobra.Command{
		Use:   "enable",
		Short: "Set auto-update mode to prompt",
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runAutoUpdateSet(cmd.OutOrStdout(), settings.AutoUpdatePrompt)
		},
	})

	cmd.AddCommand(&cobra.Command{
		Use:   "disable",
		Short: "Set auto-update mode to off",
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runAutoUpdateSet(cmd.OutOrStdout(), settings.AutoUpdateOff)
		},
	})

	cmd.AddCommand(&cobra.Command{
		Use:   "set <off|prompt|auto>",
		Short: "Set auto-update mode explicitly",
		Args:  cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			mode := args[0]
			if !settings.IsValidAutoUpdate(mode) {
				fmt.Fprintf(cmd.ErrOrStderr(),
					"invalid mode %q: must be %q, %q, or %q\n",
					mode, settings.AutoUpdateOff, settings.AutoUpdatePrompt, settings.AutoUpdateAuto)
				return NewSilentError(fmt.Errorf("invalid mode: %s", mode))
			}
			return runAutoUpdateSet(cmd.OutOrStdout(), mode)
		},
	})

	return cmd
}

func runAutoUpdateStatus(w io.Writer) error {
	g, err := settings.LoadGlobal()
	if err != nil {
		return fmt.Errorf("loading global settings: %w", err)
	}
	path, err := settings.GlobalSettingsPath()
	if err != nil {
		return fmt.Errorf("resolving settings path: %w", err)
	}
	fmt.Fprintf(w, "auto_update: %s\n", g.GetAutoUpdate())
	fmt.Fprintf(w, "config: %s\n", path)
	return nil
}

func runAutoUpdateSet(w io.Writer, mode string) error {
	g, err := settings.LoadGlobal()
	if err != nil {
		return fmt.Errorf("loading global settings: %w", err)
	}
	g.AutoUpdate = mode
	if err := settings.SaveGlobal(g); err != nil {
		return fmt.Errorf("saving global settings: %w", err)
	}
	fmt.Fprintf(w, "auto_update set to %s (updated %s)\n", mode, time.Now().Format(time.RFC3339))
	return nil
}

package cli

import (
	"github.com/spf13/cobra"

	"github.com/entireio/cli/cmd/entire/cli/versioncheck"
)

func newUpdateCmd() *cobra.Command {
	var checkOnly, skipPrompt bool

	cmd := &cobra.Command{
		Use:   "update",
		Short: "Update Entire CLI to the latest version",
		Long: `Run the installer for the current install method (brew, scoop, or install.sh).

The installer is resolved from ~/.config/entire/install.json, with a fallback
to the executable path when provenance is missing.

Flags:
  --check-only  Print the installer command without running it.
  --yes         Skip the confirmation prompt.`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			_, err := versioncheck.RunUpdateNow(cmd.Context(), cmd.OutOrStdout(), checkOnly, skipPrompt)
			return err
		},
	}

	cmd.Flags().BoolVar(&checkOnly, "check-only", false, "Print the installer command without running it")
	cmd.Flags().BoolVar(&skipPrompt, "yes", false, "Skip the confirmation prompt")
	return cmd
}

